package aws

// discoverableCFNTypes is the curated list of CloudFormation type names
// that the v1 live-AWS discovery loop will list+get via the CloudControl
// API. Picked for coverage of the most common workload patterns — every
// entry must:
//
//   1. Resolve to a CB-authored primitive via cfnTypeToCBPrimitive
//      (lives in internal/audit; generated by tools/genprimitives), so
//      the grounded analyzer can ask CB for opinions on them. The one
//      exception is AWS::EC2::EIP — see the comment at the EIP entry.
//   2. Be supported by the CloudControl API. Types absent from the CFN
//      registry surface UnsupportedActionException at list time and are
//      filtered out silently per type. The set below is the conservative
//      coverage minimum; v1.1+ extends it as we get real-user feedback.
//
// Globally-scoped types (IAM, CloudFront, Route53) are marked Global so
// the per-region fan-out only lists them once.
var discoverableCFNTypes = []cfnTypeSpec{
	// --- global ---
	{Type: "AWS::IAM::Role", Global: true},
	{Type: "AWS::IAM::ManagedPolicy", Global: true},
	{Type: "AWS::CloudFront::Distribution", Global: true},
	{Type: "AWS::Route53::HostedZone", Global: true},

	// --- regional storage ---
	{Type: "AWS::S3::Bucket"}, // S3 is regional but listable globally; treat as regional and dedupe by ARN
	{Type: "AWS::EC2::Volume"},

	// --- regional compute ---
	{Type: "AWS::EC2::Instance"},
	{Type: "AWS::Lambda::Function"},
	{Type: "AWS::ECS::Cluster"},
	{Type: "AWS::ECS::Service"},
	{Type: "AWS::AutoScaling::AutoScalingGroup"},

	// --- regional networking ---
	{Type: "AWS::EC2::VPC"},
	{Type: "AWS::EC2::Subnet"},
	{Type: "AWS::EC2::SecurityGroup"},
	{Type: "AWS::EC2::InternetGateway"},
	{Type: "AWS::EC2::NatGateway"},
	// AWS::EC2::EIP intentionally has no entry in cfnTypeToCBPrimitive —
	// it's a pure hygiene/cost resource (associated or not) with no CB
	// best-practice opinion worth grounding. Discovered solely so the
	// orphan provider can flag unassociated addresses.
	{Type: "AWS::EC2::EIP"},
	{Type: "AWS::ElasticLoadBalancingV2::LoadBalancer"},

	// --- regional data ---
	{Type: "AWS::RDS::DBInstance"},
	{Type: "AWS::RDS::DBCluster"},
	{Type: "AWS::DynamoDB::Table"},

	// --- regional messaging ---
	{Type: "AWS::SQS::Queue"},
	{Type: "AWS::SNS::Topic"},
	{Type: "AWS::Events::Rule"},

	// --- regional ops / observability ---
	{Type: "AWS::Logs::LogGroup"},
	{Type: "AWS::CloudWatch::Alarm"},
	{Type: "AWS::SecretsManager::Secret"},
	{Type: "AWS::KMS::Key"},
}

// cfnTypeSpec describes one type to list during discovery.
type cfnTypeSpec struct {
	Type   string // CFN type name, e.g. "AWS::S3::Bucket"
	Global bool   // true for IAM / CloudFront / Route53 / etc.
}

// pickRegionForGlobal returns the region to use when listing a Global
// type. AWS global services are reachable from any region but the SDK
// still needs one set; us-east-1 is the canonical home for IAM / CF /
// Route53.
const pickRegionForGlobal = "us-east-1"
